#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    int countEqualScoreSubstrings(string s) {
        int n = s.size();
        vector<int> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            pref[i + 1] = pref[i] + (s[i] - 'a' + 1);
        }
        int count = 0;
        for (int len = 2; len <= n; len += 2) {
            int k = len / 2;
            for (int start = 0; start <= n - len; ++start) {
                int left_sum = pref[start + k] - pref[start];
                int right_sum = pref[start + len] - pref[start + k];
                if (left_sum == right_sum) count++;
            }
        }
        return count;
    }
};

class Solution {
    public int countEqualScoreSubstrings(String s) {
        int n = s.length();
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + (s.charAt(i) - 'a' + 1);
        }
        int count = 0;
        for (int len = 2; len <= n; len += 2) {
            int k = len / 2;
            for (int start = 0; start <= n - len; start++) {
                int leftSum = pref[start + k] - pref[start];
                int rightSum = pref[start + len] - pref[start + k];
                if (leftSum == rightSum) count++;
            }
        }
        return count;
    }
}

var countEqualScoreSubstrings = function(s) {
    const n = s.length;
    const pref = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + (s.charCodeAt(i) - 96);
    }
    let count = 0;
    for (let len = 2; len <= n; len += 2) {
        const k = Math.floor(len / 2);
        for (let start = 0; start <= n - len; start++) {
            const leftSum = pref[start + k] - pref[start];
            const rightSum = pref[start + len] - pref[start + k];
            if (leftSum === rightSum) count++;
        }
    }
    return count;
};
